for q in r['requests']:
 t=q['generated_text'];mechanical.append({'index':q['index'],'blank_line_blocks':len([p for p in re.split(r'\n\s*\n',t.strip()) if p.strip()]),'contains_code_fence':'```' in t,'completed_action_phrase_heuristic':bool(re.search(r'\bI (?:have |had )?(?:modified|changed|ran|executed|updated|applied|fixed)\b',t,re.I))})
